('act-2', 'Lawatan Ilmiah & Sesi Mentor AI ke NVIDIA AI Technology Centre', '2026-09-28', 'Lawatan Industri', 'Rombongan 40 mahasiswa AISA mengadakan lawatan ke pusat penyelidikan NVIDIA Kuala Lumpur untuk memahami infrastruktur superkomputer AI DGX SuperPOD.', 'https://images.unsplash.com/photo-1485827404703-89b55fcc595e?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=800&q=80"]', 40, 'Peluang Latihan Industri & Pensijilan Deep Learning Institute (DLI)', 'Autonomous Agents & Large Language Models (LLM)', 'NVIDIA AI Technology Centre, Cyberjaya'),
('act-3', 'AISA Internal Datathon: Cabaran Ramalan Cuaca & Hasil Tuai', '2026-08-15', 'Hackathon', 'Pertandingan analisis siri masa cuaca dan ramalan hasil tuaian padi Sungai Rambai melibatkan mahasiswa gabungan FSKM dan FPA.', 'https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1504384308090-c894fdcc538d?auto=format&fit=crop&w=800&q=80"]', 85, 'Model Ramalan Mencapai 91.4% Ketepatan Pengesanan Anomali', 'Data Engineering & Predictive Analytics', 'Dewan Kuliah 1, FSKM UiTM Jasin');
